#!/usr/bin/env python3
"""Build the full interactive public runbook from canonical JSON."""
from __future__ import annotations

import argparse
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
DEFAULT_RUNBOOK = ROOT / "case-studies/ai-engineer-integrity/output/runbook.json"
DEFAULT_OUTPUT = ROOT / "case-studies/ai-engineer-integrity/output/runbook-demo.html"


def build(data: dict) -> str:
    payload = json.dumps(data, ensure_ascii=False).replace("</", "<\\/")
    return TEMPLATE.replace("__RUNBOOK_JSON__", payload)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--runbook", type=Path, default=DEFAULT_RUNBOOK)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    args = parser.parse_args()
    data = json.loads(args.runbook.read_text(encoding="utf-8"))
    args.output.write_text(build(data), encoding="utf-8")
    return 0


TEMPLATE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CareerLens · Personalized AI Engineer Runbook</title>
<style>
:root{--b:#08101d;--s:#101b2e;--s2:#15243b;--l:#293955;--t:#eef4ff;--m:#9aabc5;--c:#4ed5e8;--g:#5ee0a0;--v:#aa91ff;--a:#ffc968;--r:#ff7f91}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 80% 0,#1b3153 0,transparent 30%),var(--b);color:var(--t);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased}.shell{display:grid;grid-template-columns:250px minmax(0,1fr);min-height:100vh}.side{position:sticky;top:0;height:100vh;border-right:1px solid var(--l);background:#08101df2;padding:24px 16px;z-index:3}.brand{font-weight:850;font-size:16px;line-height:1.35;margin:4px 8px 20px}.brand span,a{color:var(--c)}.case{font-size:11px;color:var(--m);padding:0 8px 15px;line-height:1.5}.nav button{width:100%;min-height:42px;text-align:left;border:0;background:transparent;color:var(--m);padding:10px 12px;border-radius:9px;cursor:pointer;margin:2px 0;font-weight:650}.nav button:hover,.nav button.active{background:var(--s2);color:var(--t)}.sidefoot{position:absolute;left:24px;bottom:22px;color:var(--m);font-size:11px}.sidefoot b{color:var(--g)}main{max-width:1430px;padding:38px 38px 80px;min-width:0}.page{display:none}.page.active{display:block}.eye{color:var(--c);font-size:12px;letter-spacing:.1em;text-transform:uppercase}.hero h1{font-size:44px;line-height:1.06;letter-spacing:-1.6px;max-width:1080px;margin:12px 0;text-wrap:balance}.hero p,.note{color:var(--m);line-height:1.65;text-wrap:pretty}.hero p{max-width:980px}.grid{display:grid;gap:14px}.g4{grid-template-columns:repeat(4,1fr)}.g3{grid-template-columns:repeat(3,1fr)}.g2{grid-template-columns:repeat(2,1fr)}.card{border:1px solid var(--l);background:linear-gradient(145deg,#101b2ef8,#0a121ff8);border-radius:16px;padding:19px;min-width:0}.card h2,.card h3{margin:0 0 10px;text-wrap:balance}.kpi{font-size:34px;font-weight:850;color:var(--c);font-variant-numeric:tabular-nums}.small{color:var(--m);font-size:12px;line-height:1.55}.st{margin:32px 0 14px;font-size:23px;text-wrap:balance}.bar{height:7px;background:#1d2a42;border-radius:8px;margin:10px 0;overflow:hidden}.bar i{display:block;height:100%;border-radius:8px;background:linear-gradient(90deg,var(--v),var(--c))}.good{color:var(--g)}.warn,.pri{color:var(--a)}.bad{color:var(--r)}.violet{color:var(--v)}.call{border-left:3px solid var(--g);background:#5ee0a012;padding:16px;border-radius:8px;line-height:1.65}.filters{display:flex;gap:9px;flex-wrap:wrap;margin:14px 0}.filters input,.filters select{min-height:42px;background:var(--s);border:1px solid var(--l);color:var(--t);padding:10px 12px;border-radius:9px}.filters input{min-width:300px;flex:1}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px}.progress{font-size:12px;color:var(--g);font-variant-numeric:tabular-nums}button.action{min-height:42px;border:1px solid var(--l);background:var(--s2);color:var(--t);border-radius:9px;padding:9px 12px;cursor:pointer;font-weight:700;transition-property:transform,border-color;transition-duration:120ms}button.action:active{transform:scale(.96)}.state,.tag{display:inline-block;font-size:10px;padding:3px 7px;border-radius:999px;background:#1c2a43}.state.proved{color:var(--g)}.state.claimed{color:var(--a)}.state.missing{color:var(--r)}.state.unknown{color:var(--v)}.module{border-left:3px solid var(--l)}.module.enabled{border-left-color:var(--g)}.module.deferred{border-left-color:var(--a)}.module.suppressed{border-left-color:var(--m)}.factor{display:grid;grid-template-columns:145px 100px 1fr;gap:12px;padding:12px 0;border-bottom:1px solid var(--l);font-size:13px}.factor:last-child{border:0}.round{display:grid;grid-template-columns:130px 1fr 1fr 110px;gap:12px;padding:14px 0;border-bottom:1px solid var(--l);font-size:12px}.round:last-child{border:0}details{border:1px solid var(--l);border-radius:12px;margin:9px 0;background:#101b2e9e}summary{cursor:pointer;padding:14px;font-weight:750;list-style-position:outside}details>div{padding:0 15px 16px;color:#c8d4e8;line-height:1.62;font-size:13px}.qmeta{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:10px}.qmeta span{font-size:10px;padding:3px 7px;border-radius:999px;background:#1c2a43;color:var(--m)}.resource{position:relative}.resource .order{position:absolute;right:16px;top:14px;color:var(--c);font-size:11px}.resource dl{display:grid;grid-template-columns:105px 1fr;gap:7px 10px;font-size:12px}.resource dt{color:var(--m)}.resource dd{margin:0;color:#c8d4e8}.check{display:flex;gap:10px;align-items:flex-start}.check input{margin-top:4px;accent-color:var(--g)}.task{border-left:3px solid var(--v)}.task.done{opacity:.62}.task.done h3{text-decoration:line-through}.tasktop{display:flex;justify-content:space-between;gap:10px}.task .hours{color:var(--c);font-variant-numeric:tabular-nums}.phasehead{display:flex;justify-content:space-between;gap:12px;align-items:start}.source{font-size:11px;color:var(--m);line-height:1.65}.truth{border-left-color:var(--a)}.empty{padding:30px;text-align:center;color:var(--m)}:focus-visible{outline:2px solid var(--c);outline-offset:2px}
@media(max-width:950px){.shell{grid-template-columns:1fr}.side{position:sticky;height:auto;border-right:0;border-bottom:1px solid var(--l);padding:12px}.brand{margin:0 8px 7px}.case,.sidefoot{display:none}.nav{display:flex;overflow:auto}.nav button{min-width:max-content}.g4,.g3{grid-template-columns:repeat(2,1fr)}main{padding:24px 16px}.hero h1{font-size:34px}.round{grid-template-columns:1fr 1fr}.factor{grid-template-columns:120px 80px 1fr}}
@media(max-width:620px){.g4,.g3,.g2{grid-template-columns:1fr}.toolbar{align-items:stretch;flex-direction:column}.filters input{min-width:100%}.hero h1{font-size:31px}.round,.factor{grid-template-columns:1fr}.resource dl{grid-template-columns:1fr}.resource dt{margin-top:6px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
</style></head><body><div class="shell"><aside class="side"><div class="brand">CareerLens<br><span>Personalized Runbook</span></div><div class="case" id="caseLabel"></div><nav class="nav" id="nav"></nav><div class="sidefoot"><b>● validated</b><br>canonical JSON projection</div></aside><main id="main"></main></div>
<script id="runbook" type="application/json">__RUNBOOK_JSON__</script><script>
const d=JSON.parse(document.getElementById('runbook').textContent),main=document.getElementById('main'),nav=document.getElementById('nav');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['overview','01 Overview'],['modules','02 Module logic'],['evidence','03 Evidence map'],['rounds','04 Interview map'],['questions','05 Question bank'],['resources','06 Learning paths'],['plan','07 Preparation plan'],['guidance','08 Resume & stories'],['method','09 Method & sources']];
nav.innerHTML=pages.map((x,i)=>`<button data-page="${x[0]}" class="${i?'':'active'}">${x[1]}</button>`).join('');
const page=(id,html)=>`<section class="page${id==='overview'?' active':''}" id="${id}">${html}</section>`;
const hero=(eye,title,text)=>`<div class="hero"><div class="eye">${eye}</div><h1>${title}</h1><p>${text}</p></div>`;
const counts=Object.fromEntries(['proved','claimed','missing','unknown'].map(s=>[s,d.fit_assessment.filter(x=>x.status===s).length]));
const enabled=d.module_selection.filter(x=>x.state==='enabled').length,planned=d.roadmap.phases.flatMap(x=>x.actions).reduce((n,x)=>n+x.estimated_minutes,0),capacity=d.roadmap.weeks*d.roadmap.weekly_capacity_hours,deferred=d.module_selection.filter(x=>x.state!=='enabled').map(x=>`${x.label} is ${x.state}`).join('; ');
document.getElementById('caseLabel').innerHTML=`Public fictional candidate<br>${esc(d.target_picture.role_label)}`;
document.title=`CareerLens · ${d.target_picture.role_label} Runbook`;
main.innerHTML+=page('overview',hero('Evidence-bounded · dynamic full runbook',`Worth applying.<br><span class="warn">Prepare the proof gaps first.</span>`,esc(d.decision_state.reason))+`<div class="grid g4" style="margin-top:22px"><div class="card"><div class="kpi">${enabled}</div><div class="small">modules enabled by evidence</div></div><div class="card"><div class="kpi">${d.question_bank.length}</div><div class="small">selected questions with rationale</div></div><div class="card"><div class="kpi">${d.learning_tracks.flatMap(x=>x.resources).length}</div><div class="small">scoped learning resources</div></div><div class="card"><div class="kpi">${planned/60}h / ${capacity}h</div><div class="small">capacity-aware preparation</div></div></div><h2 class="st">Application decision</h2><div class="grid g2"><div class="card"><h3>Why conditional</h3><p class="note">${esc(d.strategy.positioning)}</p></div><div class="card"><h3>No made-up match percentage</h3><p class="note">The runbook preserves missing and unknown evidence. It recommends work without predicting an interview or offer.</p></div></div><h2 class="st">What the engine selected</h2><div class="call"><b>${enabled} modules enabled.</b> ${esc(deferred)}. Every decision is inspectable on the next page.</div>`);
main.innerHTML+=page('modules',hero('Activation before content','Why these preparation modules?',`CareerLens does not hand every candidate the same curriculum. It activates a module only when target evidence, candidate state, and expected hiring signal justify the time.`)+`<div class="grid g2" style="margin-top:22px">${d.module_selection.map(x=>`<article class="card module ${x.state}"><div><span class="state ${x.state==='enabled'?'proved':x.state==='deferred'?'claimed':'unknown'}">${x.state}</span> <span class="tag">${x.confidence} confidence</span></div><h3>${esc(x.label)}</h3><p class="note">${esc(x.reason)}</p><p class="source"><b>Evidence:</b> ${x.evidence_refs.map(esc).join(' · ')}</p></article>`).join('')}</div><h2 class="st">Selection rules</h2><div class="grid g3">${[['Questions',d.selection_methodology.question_factors],['Resources',d.selection_methodology.resource_factors],['Plan',d.selection_methodology.plan_factors]].map(([name,rows])=>`<div class="card"><h3>${name}</h3>${rows.map(x=>`<div class="factor"><b>${esc(x.factor)}</b><span class="pri">${esc(x.weight||'rule')}</span><span>${esc(x.meaning||x.rule)}</span></div>`).join('')}</div>`).join('')}</div>`);
main.innerHTML+=page('evidence',hero('Candidate proof ≠ target requirement',`${d.fit_assessment.length} requirements. Four honest states.`,`Claimed, missing, and unknown evidence stays visible. The system does not convert adjacent experience into a stronger claim.`)+`<div class="filters" id="eFilters">${['all','proved','claimed','missing','unknown'].map(x=>`<button class="action" data-state="${x}">${x==='all'?'All '+d.fit_assessment.length:x[0].toUpperCase()+x.slice(1)+' '+counts[x]}</button>`).join('')}</div><div class="grid g2" id="eGrid">${d.fit_assessment.map(x=>`<article class="card evidence" data-state="${x.status}"><span class="state ${x.status}">${x.status}</span><h3>${esc(x.label)}</h3><p class="note">${esc(x.boundary||((x.proof_refs||[]).join(' · ')||'No candidate-owned proof'))}</p></article>`).join('')}</div>`);
main.innerHTML+=page('rounds',hero('Preparation-oriented inference','Likely interview map',`These rounds are preparation categories inferred from supplied official requirements, not a claimed employer interview schedule.`)+`<div class="card" style="margin-top:22px">${d.interview_map.rounds.map((x,i)=>`<div class="round"><b>${String(i+1).padStart(2,'0')} · ${esc(x.label)}</b><span>${esc(x.purpose)}</span><span class="note">Mapped questions: ${d.question_bank.filter(q=>(q.mapped_rounds||[]).includes(x.round_id)).length}</span><span class="pri">prepare</span></div>`).join('')}</div><div class="call" style="margin-top:16px">${esc(d.interview_map.boundary)}</div>`);
main.innerHTML+=page('questions',hero('Coverage before volume','Questions selected for this candidate',`Each item shows why it entered the runbook, which requirement and round it covers, and what “done” means.`)+`<div class="filters"><input id="qSearch" placeholder="Search question, requirement, rationale"><select id="qPriority"><option value="">All priorities</option><option>A</option><option>B</option><option>C</option></select><select id="qKind"><option value="">All modules</option>${[...new Set(d.question_bank.map(x=>x.kind))].map(x=>`<option>${x}</option>`).join('')}</select></div><div id="qCount" class="progress"></div><div id="qList"></div>`);
main.innerHTML+=page('resources',hero('Customized, not collected','Read less. Produce more.',`Resources are assigned from the candidate’s starting state. Every link has a distinct job, a scoped reading assignment, skip guidance, time budget, and required output.`)+`<div class="call" style="margin-top:22px"><b>Selection boundary:</b> one framework, one mechanism reference, one production case, and one practice resource when each adds distinct value. Authority alone does not justify assigning an entire document.</div>${d.learning_tracks.map(t=>`<h2 class="st">${esc(t.title)}</h2><div class="grid g2">${t.resources.map(r=>`<article class="card resource"><span class="order">Step ${r.sequence} · ${r.estimated_minutes}m</span><span class="tag">${esc(r.resource_role)}</span><h3><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)} ↗</a></h3><dl><dt>Your starting point</dt><dd>${esc(r.candidate_starting_state)}</dd><dt>Why assigned</dt><dd>${esc(r.why_it_fits)}</dd><dt>Read only</dt><dd>${esc(r.reading_scope)}</dd><dt>Skip</dt><dd>${esc(r.skip_guidance)}</dd><dt>Produce</dt><dd>${esc(r.assigned_output)}</dd><dt>Done when</dt><dd>${esc(r.completion_condition)}</dd><dt>Supports</dt><dd>${r.mapped_question_ids.map(esc).join(' · ')}</dd></dl></article>`).join('')}</div>`).join('')}`);
main.innerHTML+=page('plan',hero('Risk × transfer × dependency',`A ${planned/60}-hour plan inside ${capacity} available hours`,`High-risk credibility gaps come first. Mechanism learning precedes design and mocks. Every task produces an artifact and has an exit gate.`)+`<div class="grid g4" style="margin-top:22px"><div class="card"><div class="kpi">${planned/60}h</div><div class="small">planned</div></div><div class="card"><div class="kpi">${capacity}h</div><div class="small">available</div></div><div class="card"><div class="kpi">${d.roadmap.phases.length}</div><div class="small">gated phases</div></div><div class="card"><div class="kpi" id="doneKpi">0%</div><div class="small">completed locally</div></div></div><div class="bar"><i style="width:${planned/(capacity*60)*100}%"></i></div>${d.roadmap.phases.map(p=>`<h2 class="st phasehead"><span>${esc(p.week_range)} · ${esc(p.label)}</span><span class="tag">phase gate</span></h2><div class="call"><b>Why now:</b> ${esc(p.rationale)}<br><b>Advance when:</b> ${esc(p.exit_gate)}</div><div class="grid g2" style="margin-top:14px">${p.actions.map(a=>`<label class="card task check"><input type="checkbox" data-task="${a.action_id}"><div><div class="tasktop"><span class="pri">Priority ${a.priority}</span><span class="hours">${a.estimated_minutes/60}h</span></div><h3>${esc(a.title)}</h3><p class="note">${esc(a.completion_condition)}</p><p class="small"><b>Artifact:</b> ${esc(a.artifact)}</p><p class="small"><b>Exit gate:</b> ${esc(a.exit_gate)}</p><p class="source">Depends on: ${(a.dependencies||[]).map(esc).join(' · ')||'none'} · Questions: ${(a.linked_question_ids||[]).map(esc).join(' · ')}</p></div></label>`).join('')}</div>`).join('')}`);
main.innerHTML+=page('guidance',hero('Strengthen proof, never invent it','Resume and story guidance',`Every recommendation states why the defect matters, how to repair it safely, and the boundary the candidate must not cross.`)+`<div class="grid g2" style="margin-top:22px">${d.resume_guidance.map(x=>`<article class="card"><span class="pri">Priority ${x.priority}</span><h3>${esc(x.finding_id.replaceAll('-',' '))}</h3><p class="note">${esc(x.why_it_matters)}</p><p><b>Safe direction</b><br><span class="small">${esc(x.safe_direction)}</span></p><p class="bad"><b>Truth boundary</b></p><p class="small">${esc(x.truth_boundary)}</p><p><b>Done when</b><br><span class="small">${esc(x.completion_check)}</span></p></article>`).join('')}</div>`);
main.innerHTML+=page('method',hero('Auditable inputs and limits','Method, sources, and exclusions',`The canonical artifact records candidate facts, target evidence, inference, uncertainty, resource scope, and planning capacity separately.`)+`<h2 class="st">Source ledger</h2><div class="grid g2">${d.sources.map(x=>`<article class="card"><span class="tag">${esc(x.source_class)}</span><h3><a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.title)} ↗</a></h3><p class="note">${esc(x.claim_scope)}</p><p class="source">${esc(JSON.stringify(x.freshness))}</p></article>`).join('')}</div><h2 class="st">Stop rules</h2><div class="card truth">${d.strategy.stop_rules.map(x=>`<p>• ${esc(x)}</p>`).join('')}</div><h2 class="st">What was intentionally excluded</h2><div class="grid g2">${d.module_selection.filter(x=>x.state!=='enabled').map(x=>`<div class="card"><h3>${esc(x.state)}: ${esc(x.label)}</h3><p class="note">${esc(x.reason)}</p></div>`).join('')}</div>`);
function show(id){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===id));scrollTo({top:0,behavior:'smooth'});history.replaceState(null,'','#'+id)}
nav.addEventListener('click',e=>{const b=e.target.closest('button');if(b)show(b.dataset.page)});
document.getElementById('eFilters').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('#eGrid .evidence').forEach(x=>x.hidden=b.dataset.state!=='all'&&x.dataset.state!==b.dataset.state)});
function renderQ(){const s=qSearch.value.toLowerCase(),p=qPriority.value,k=qKind.value;const rows=d.question_bank.filter(x=>(JSON.stringify(x).toLowerCase().includes(s))&&(!p||x.priority===p)&&(!k||x.kind===k));qCount.textContent=`Showing ${rows.length} / ${d.question_bank.length} · Priority A ${rows.filter(x=>x.priority==='A').length}`;qList.innerHTML=rows.map(x=>`<details><summary><span class="pri">P${x.priority}</span> · ${esc(x.prompt)}</summary><div><div class="qmeta"><span>${esc(x.kind)}</span><span>${esc(x.confidence)} confidence</span>${x.mapped_rounds.map(r=>`<span>${esc(r)}</span>`).join('')}</div><p><b>Why selected:</b> ${esc(x.selection_reason)}</p><p><b>Candidate connection:</b> ${esc(x.candidate_relevance)}</p><p><b>Requirements:</b> ${x.mapped_requirements.map(esc).join(' · ')}</p><p><b>Done when:</b> ${esc(x.completion_standard)}</p></div></details>`).join('')||'<div class="empty">No questions match these filters.</div>'}qSearch.oninput=renderQ;qPriority.onchange=renderQ;qKind.onchange=renderQ;renderQ();
const taskKey='careerlens-public-runbook-tasks-'+d.identity.runbook_id;let saved=JSON.parse(localStorage.getItem(taskKey)||'{}');function progress(){const boxes=[...document.querySelectorAll('[data-task]')];boxes.forEach(x=>{x.checked=!!saved[x.dataset.task];x.closest('.task').classList.toggle('done',x.checked)});doneKpi.textContent=Math.round(boxes.filter(x=>x.checked).length/boxes.length*100)+'%'}document.querySelectorAll('[data-task]').forEach(x=>x.onchange=()=>{saved[x.dataset.task]=x.checked;localStorage.setItem(taskKey,JSON.stringify(saved));progress()});progress();
const initial=location.hash.slice(1);if(pages.some(x=>x[0]===initial))show(initial);
</script></body></html>'''


if __name__ == "__main__":
    raise SystemExit(main())
